# ==============================================================================# 043_COMMAND_HISTORY.py# ==============================================================================import sqlite3from pathlib import PathROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")print("=" * 80)print("COMMAND HISTORY")print("=" * 80)# ------------------------------------------------------------------------------# RESUMO GERAL# ------------------------------------------------------------------------------cur.execute("""SELECTCOUNT(*) total,SUM(CASE WHEN status='EXECUTED' THEN 1 ELSE 0 END) success,AVG(execution_time) avg_time,MIN(execution_time) min_time,MAX(execution_time) max_timeFROM command_history""")summary = cur.fetchone()total = summary["total"] or 0success = summary["success"] or 0avg_time = summary["avg_time"] or 0min_time = summary["min_time"] or 0max_time = summary["max_time"] or 0rate = (success / total * 100) if total else 0print(f"TOTAL COMMANDS....: {total}")print(f"SUCCESS...........: {success}")print(f"SUCCESS RATE......: {rate:.2f}%")print(f"AVG TIME..........: {avg_time:.6f} s")print(f"MIN TIME..........: {min_time:.6f} s")print(f"MAX TIME..........: {max_time:.6f} s")print("=" * 80)# ------------------------------------------------------------------------------# PRIORIDADES# ------------------------------------------------------------------------------print("COMMANDS BY PRIORITY")print("-" * 80)cur.execute("""SELECTpriority,COUNT(*) totalFROM command_historyGROUP BY priorityORDER BYCASE priorityWHEN 'CRITICAL' THEN 1WHEN 'HIGH' THEN 2WHEN 'NORMAL' THEN 3WHEN 'LOW' THEN 4END""")for row in cur.fetchall():    print(f"{row['priority']:<10} {row['total']}")print("=" * 80)# ------------------------------------------------------------------------------# HISTÃ"RICO# ------------------------------------------------------------------------------print("LAST COMMANDS")print("-" * 80)cur.execute("""SELECTcommand_name,target_service,priority,execution_time,statusFROM command_historyORDER BY id DESCLIMIT 20""")for row in cur.fetchall():    print(        f"{row['priority']:<9}"        f"{row['command_name']:<24}"        f"{row['target_service']:<20}"        f"{row['execution_time']:.6f}s  "        f"{row['status']}"    )print("=" * 80)conn.close()

